/** Find the home system's first landable-atmosphere planet anchor. */
function homePlanetAnchor(playerId: string): { systemId: string; anchor: { x: number; z: number }; atmoR: number } | null {
  const systemId = homeSystemIdForPlayer(SEED, playerId);
  const system = systemForId(SEED, systemId);
  if (!system) return null;
  const idx = system.planets.findIndex((p) => p.landable && p.hasAtmosphere);
  if (idx < 0) return null;
  const anchor = planetAnchor(idx);
  return { systemId, anchor, atmoR: planetAtmosphereRadius(system.planets[idx]) };
}

